#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
priority_queue<long long>pq(a.begin(),a.end());
bool first=true;
while(!pq.empty()){if(!first)printf(" ");printf("%lld",pq.top());pq.pop();first=false;}
printf("\n");return 0;}

